query:
UPDATE course_lessons SET content = REPLACE(
  REPLACE(
    REPLACE(content,
      '*   **t062 [Anlg In2 Sel]:** Set to `2` (4-20mA).',
      '*   **P047 [Anlg In Config]:** Set to `1` (4-20mA on Terminal 15). *Note: The PowerFlex 525 has one analog input — use Terminal 15 for 4-20mA current input.*'
    ),
    '*   **t063 [Anlg In2 Lo]:** Set to `20.0%` (This corresponds to 4mA, which is 20% of the 0-20mA range).',
    '*   **t060 [Anlg In Lo]:** Set to `0.0%` (4mA = process minimum).'
  ),
  '*   **t064 [Anlg In2 Hi]:** Set to `100.0%` (This corresponds to 20mA).',
  '*   **t061 [Anlg In Hi]:** Set to `100.0%` (20mA = process maximum).'
) WHERE id = 30023;

